"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function ExpertHomePage() {
  const router = useRouter();
  const [competitionId, setCycleId] = useState("");

  function onOpenQueue(e: FormEvent) {
    e.preventDefault();
    const id = competitionId.trim();
    if (!id) return;
    router.push(`/expert/competitions/${id}/queue`);
  }

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Assessor portal"
        description="Open your conflict-filtered scoring queue for a competition cycle, then enter rubric marks in blind mode when configured."
      />

      <Card>
        <CardHeader>
          <h2 className="text-lg font-semibold">Scoring queue</h2>
          <CardDescription>
            Enter the competition ID for your assignment. The queue uses your signed-in
            expert account — no competitor identity is listed when blind mode is
            on.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onOpenQueue} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="competitionId">Competition ID</Label>
              <Input
                id="competitionId"
                className="min-h-11"
                value={competitionId}
                onChange={(e) => setCycleId(e.target.value)}
                required
                autoComplete="off"
                data-testid="expert-cycle-id"
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              data-testid="expert-open-queue"
            >
              Open queue
            </Button>
          </form>
        </CardContent>
      </Card>

      <p className="text-xs text-muted-foreground">
        <Link href="/" className="underline underline-offset-2">
          Back to home
        </Link>
      </p>
    </PageShell>
  );
}
